using System;using System.Windows.Forms;using GymAndFitnessManagementSystem.Common;using GymAndFitnessManagementSystem.Data;
namespace GymAndFitnessManagementSystem.Forms{public class ReviewForm:Form{int item;NumericUpDown rating=new NumericUpDown{Minimum=1,Maximum=5,Value=5};TextBox comment=new TextBox{Multiline=true};public ReviewForm(int id){item=id;Theme.Apply(this,"Review");Size=new System.Drawing.Size(600,460);Controls.Add(Theme.Header("Rate & Review (1-5)"));var p=new Panel{Dock=DockStyle.Fill,Padding=new Padding(90,35,90,35)};Controls.Add(p);p.Controls.Add(new Label{Text="Rating",Left=90,Top=40,Width=300});rating.SetBounds(90,70,100,30);p.Controls.Add(rating);p.Controls.Add(new Label{Text="Comment",Left=90,Top=120,Width=300});comment.SetBounds(90,150,390,100);p.Controls.Add(comment);var b=Theme.Button("Submit Review",(o,e)=>{Repositories.AddReview(Session.UserId,item,(int)rating.Value,comment.Text);MessageBox.Show("Review saved.");Close();});b.SetBounds(90,280,170,42);p.Controls.Add(b);var c=Theme.Button("Cancel",(o,e)=>Close());c.SetBounds(280,280,150,42);p.Controls.Add(c);}}}
